 public void changed(){ui.select(selectedTab);progress.setText(jobs.status+" "+jobs.progress);history.setText(conversation);String events="";JSONArray a=jobs.report.optJSONArray("events");if(a!=null)for(int i=Math.max(0,a.length()-8);i<a.length();i++)events+="• "+a.optJSONObject(i).optString("message")+"\n";progress.append("\n"+events);diff.setText(proposal==null?"暂无待执行修改。":proposal.optString("summary")+"\n文件："+proposedPath+"\n\n修改前：\n"+proposal.optString("before")+"\n\n修改后：\n"+proposal.optString("after"));apply.setEnabled(!jobs.busy&&proposal!=null);ask.setEnabled(!jobs.busy);export.setEnabled(!jobs.busy&&jobs.file(2).isFile());rollback.setEnabled(!jobs.busy&&new File(jobs.root,"ai-backup.zip").isFile());}
 public void onDestroy(){jobs.detach(this);super.onDestroy();}public void onResume(){super.onResume();if(jobs!=null)jobs.listen(this);}
 void save(int code,String name){if(jobs.busy)return;Intent i=new Intent("android.intent.action.CREATE_DOCUMENT");i.setType(code==MODULE?"application/zip":"text/plain");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_TITLE,name);startActivityForResult(i,code);}
 protected void onActivityResult(final int req,int code,Intent data){super.onActivityResult(req,code,data);if(code!=RESULT_OK||data==null||data.getData()==null)return;final Uri uri=data.getData();if(req==LOG)jobs.begin("读取并脱敏错误日志",new Jobs.Work(){public void run(Jobs j)throws Exception{GameLogs.importLog(j,uri,"AI页导入游戏日志");final String text=GameLogs.text(j);runOnUiThread(new Runnable(){public void run(){log.setText(text);}});j.stage("ai-log-loaded","日志已载入，可预览后发送分析");}});else if(req==MODULE||req==REPORT)jobs.exportTask(new Jobs.Work(){public void run(Jobs j)throws Exception{OutputStream out=getContentResolver().openOutputStream(uri);FilesEx.require(out!=null,"E_EXPORT_OPEN");try{if(req==MODULE){j.engine().module(j.file(2));InputStream in=new FileInputStream(j.file(2));try{FilesEx.copy(in,out,j);}finally{in.close();}}else out.write(AiClient.redact(conversation,config.secret()).getBytes("UTF-8"));}finally{out.close();}}});}
